// Shared catalogue tables keep headings once, numeric columns aligned, and identity fixed.
function catalogueTable(name,heads,rows,classes=''){
 return `<div class="table-wrap dense-table-wrap" tabindex="0" aria-label="${esc(name)}，可横向滚动"><table class="dense-table ${classes}"><caption class="visually-hidden">${esc(name)}</caption><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${heads.length}" class="muted">没有匹配记录，请调整筛选。</td></tr>`}</tbody></table></div>`;
}
// Fixed scales keep the same value visually stable when filtering or sorting.
function catalogueStat(value,{scale=30,signed=false,label=''}={}){
 const raw=String(value??'—'),parts=raw.replace(/−/g,'-').match(/-?\d+(?:\.\d+)?/g),number=Number(raw.replace(/−/g,'-'));
 if(!parts)return `<span class="catalog-stat-missing">${esc(raw)}</span>`;
 const magnitude=Number.isFinite(number)?Math.abs(number):Math.max(...parts.map(v=>Math.abs(Number(v)))),negative=Number.isFinite(number)&&number<0;
 const level=magnitude===0?0:Math.min(4,Math.max(1,Math.ceil(magnitude/scale*4)));
 const text=signed&&number>0?'+'+raw:raw;
 return `<span class="catalog-stat tone-${level}${negative?' stat-hatched':''}" title="${esc(label)} ${esc(text)}；底色深浅表示数值大小${negative?'，斜纹表示负值':''}">${esc(text)}</span>`;
}
function equipmentStat(value,label){return catalogueStat(value,{label,scale:({威力:40,命中:100,必杀:40,重量:20,射程:5,耐久:100}[label]||20)})}
function equipmentRequirementTags(value){
 const names={剑:'剑术',剣:'剑术',枪:'枪术',槍:'枪术',斧:'斧术',弓:'弓术',格:'格斗术'};
 return esc(value||'').replace(/(剑术|枪术|斧术|弓术|格斗术|剑|剣|枪|槍|斧|弓|格)\s*([EDCBAS]\+?)/g,(_,name,rank)=>`<span class="qualification-token">${tag((names[name]||name)+' '+rank)}</span>`);
}
function classRequirementTokens(c){
 const token=([name,rank])=>`<span class="qualification-token">${tag(name+' '+rank)}</span>`,parts=(c.must||[]).map(token);
 if(c.any?.length)parts.push(`<span class="qualification-alternatives">${c.must?.length?'（':''}${c.any.map(token).join('<small class="requirement-or">或</small>')}${c.must?.length?'）':''}</span>`);
 return [c.col_2?`<span>${esc(c.col_2)}</span>`:'',parts.join('<small class="requirement-and">＋</small>')].filter(Boolean).join(' ')||'<span class="muted">无专精要求</span>';
}
function classTable(list){
 const keys=CLASS_GROWTH_ORDER;
 return catalogueTable('职业成长修正（百分点）',['职业 / 移动','转职资格',...keys.map(k=>statNames[k]),'合计','熟练奖励 / 可用专精'],list.map(c=>{const skill=masteryEffect(c);return `<tr><th scope="row"><div class="catalog-identity">${classIcon(c,32)}<div><button class="text-button" data-reference-type="class" data-reference-id="${c.id}">${esc(c.cn)}</button><small>移动 ${esc(c.col_34||'—')}</small></div></div></th><td class="catalog-requirements"><div class="qualification-tokens">${classRequirementTokens(c)}</div>${c.unlock?`<button class="text-button unlock-reference" data-reference-type="class" data-reference-id="${c.id}" title="${escapeAttr(c.unlock)}">解锁条件 ↗</button>`:''}${c.col_41?`<small class="muted">${esc(c.col_41)}</small>`:''}</td>${[...keys,'total'].map(k=>{const v=classGrowthValue(c,k);return `<td class="catalog-number ${v<0?'negative':v>0?'positive':'zero'} ${classSort===k?'sorted':''}" title="${esc(k==='total'?'修正合计':statNames[k])} ${v>0?'+':''}${v} 个百分点">${catalogueStat(v,{signed:true,scale:k==='total'?120:30,label:k==='total'?'修正合计':statNames[k]})}</td>`}).join('')}<td class="catalog-mastery"><button class="text-button" data-reference-type="class" data-reference-id="${c.id}" title="${escapeAttr(skill?.description||'')}">${esc(c.col_37||'—')}</button><div class="class-skill-list">${(c.allowedSkills||[]).map(n=>tag(n)).join('')}</div></td></tr>`}).join(''),'class-data-table');
}
function equipmentTable(list){
 const keys=['威力','命中','必杀','重量','射程','耐久'];
 return catalogueTable('装备性能',['装备 / 资格',...keys,'效果与获取','推荐角色'],list.map(e=>{const metrics=equipmentMetrics(e),values=new Map(metrics.map(([,k,v])=>[k,v]));const description=equipmentCard(e).match(/<p class="equipment-row-effect">([\s\S]*?)<\/p>/)?.[1]||esc(e.effect),kinds=[...new Set((e.sourcesList||[]).map(s=>s.kind).filter(Boolean))];const info=`<p class="equipment-row-effect">${description}</p><div class="equipment-source-preview catalog-source-line"><button class="text-button" data-reference-type="equipment" data-reference-id="${e.id}" title="${escapeAttr(e.sourcesList.map(s=>s.text).join('；'))}">${esc(kinds.slice(0,3).join(' / '))}${kinds.length>3?'等':''} ↗</button>${e.maxForge?`<button class="text-button" data-reference-type="equipment" data-reference-id="${e.id}">锻造 ${esc(e.maxForge)}</button>`:''}</div>`;return `<tr id="gear-${e.id}" data-equipment-row="${e.id}"><th scope="row"><div class="catalog-identity"><span class="weapon-icon">${equipmentIcon(e)}</span><div><button class="text-button" data-reference-type="equipment" data-reference-id="${e.id}">${esc(e.name)}</button><small class="equipment-qualification">${equipmentRequirementTags(e.rank)} <span>· ${esc(e.type)}</span></small></div></div></th>${keys.map(k=>`<td class="catalog-number ${equipmentSort===k?'sorted':''}">${equipmentStat(values.get(k)??'—',k)}</td>`).join('')}<td class="catalog-equipment-info">${metrics.filter(([,k])=>!keys.includes(k)).map(([,k,v])=>`<span class="equipment-extra-stat">${esc(k)} ${equipmentStat(v,k)}</span>`).join(' ')}${info}</td><td>${peopleStack(e.recommendedBy,{max:4,label:e.name})}</td></tr>`}).join(''),'equipment-data-table');
}
function materialsPage(){
 const all=materialExchangeIndex(),list=materialRowsFor(EQUIPMENT),counts={all:all.length,exchange:all.filter(r=>r.uses.length).length,forge:all.filter(r=>r.forgeUses.length).length};
 return title('资料','材料图鉴','')+`<nav class="catalog-category-tabs" aria-label="材料分类">${[['all','全部材料'],['exchange','兑换材料'],['forge','锻造石材']].map(([key,label])=>`<button data-mat-kind="${key}" class="${materialKindFilter===key?'active':''}" aria-pressed="${materialKindFilter===key}">${label}<small>${counts[key]}</small></button>`).join('')}</nav>`+filterDeck(toolbar('搜索材料、关联武器、兑换或采集地点…',searchCount(list.length,all.length,'种材料')),[['库存','<a class="button-link" href="#collection">管理武器与材料库存 ↗</a>']])+catalogueTable('材料用途与获取',['材料','用途','关联装备与配方','获取地点'],list.map(r=>`<tr><th scope="row"><div class="catalog-identity" data-skill-images="off"><div><b>${esc(r.name)}</b>${r.aliases.length?`<small>${esc(r.aliases.join(' / '))}</small>`:''}</div></div></th><td>${esc(r.kind)}<small class="muted">${new Set(r.allUses.map(u=>u.e.id)).size} 件装备</small></td><td><div class="material-use-links">${[...new Map(r.allUses.map(u=>[u.e.id,u])).values()].slice(0,6).map(u=>`<button class="text-button" data-reference-type="equipment" data-reference-id="${u.e.id}" title="${escapeAttr(u.recipe)}${u.place?' · '+escapeAttr(u.place):''}">${esc(u.e.name)}<small>×${u.qty}${u.mode==='forge'?' · 强化':''}</small></button>`).join('')}${new Set(r.allUses.map(u=>u.e.id)).size>6?`<button class="text-button material-all-equipment" data-material-equipment="${escapeAttr(r.name)}">查看全部 ${new Set(r.allUses.map(u=>u.e.id)).size} 件 ↗</button>`:''}</div></td><td class="material-place-cell">${r.where.length?`<span>${esc(r.where.slice(0,3).join(' / '))}${r.where.length>3?` 等 ${r.where.length} 处`:''}</span>`:'<span class="muted">探索或任务获取</span>'}<button class="text-button" data-map="${escapeAttr(r.name)}">地图查看 ↗</button></td></tr>`).join(''),'material-data-table');
}
